        [MenuItem("ARNav/Setup Phase 2A Scenes")]
        public static void CreateScenesForCommandLine() { CreateScenes(); }

        public static void CreateScenes()
        {
            EnsureDirectory("Assets/ARNav/Scenes");
            EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            var boot = new GameObject("Boot"); boot.AddComponent<AppBootstrap>();
            EditorSceneManager.SaveScene(SceneManager.GetActiveScene(), "Assets/ARNav/Scenes/Boot.unity");

            EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            BuildMapSetupScene();
            EditorSceneManager.SaveScene(SceneManager.GetActiveScene(), "Assets/ARNav/Scenes/MapSetup.unity");

            EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            BuildNavigationScene();
            EditorSceneManager.SaveScene(SceneManager.GetActiveScene(), "Assets/ARNav/Scenes/Navigation.unity");

            var scenes = new[] { "Assets/ARNav/Scenes/Boot.unity", "Assets/ARNav/Scenes/MapSetup.unity", "Assets/ARNav/Scenes/Navigation.unity", "Assets/Scenes/SampleScene.unity" };
            var buildScenes = new EditorBuildSettingsScene[scenes.Length];
            for (var i = 0; i < scenes.Length; i++) buildScenes[i] = new EditorBuildSettingsScene(scenes[i], true);
            EditorBuildSettings.scenes = buildScenes;
            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
        }

