        private static Dropdown CreateDropdown(string name, Transform parent)
        {
            var root = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(Dropdown)); root.transform.SetParent(parent, false); root.GetComponent<Image>().color = new Color(0.12f, 0.18f, 0.23f, 0.96f); var dropdown = root.GetComponent<Dropdown>(); var caption = CreateText("Caption", root.transform, Vector2.zero, Vector2.zero); caption.text = "Destination"; caption.alignment = TextAnchor.MiddleCenter; SetAnchors(caption.rectTransform, Vector2.zero, Vector2.one, new Vector2(4, 0), new Vector2(-4, 0)); dropdown.captionText = caption; var template = CreateRect("Template", root.transform); template.gameObject.AddComponent<Image>(); var scroll = template.gameObject.AddComponent<ScrollRect>(); var viewport = CreateRect("Viewport", template); viewport.gameObject.AddComponent<Mask>().showMaskGraphic = false; var content = CreateRect("Content", viewport); var item = new GameObject("Item", typeof(RectTransform), typeof(Toggle)); item.transform.SetParent(content, false); var itemText = CreateText("ItemLabel", item.transform, Vector2.zero, Vector2.zero); itemText.alignment = TextAnchor.MiddleLeft; SetAnchors(itemText.rectTransform, Vector2.zero, Vector2.one, new Vector2(8, 0), Vector2.zero); scroll.viewport = viewport; scroll.content = content; dropdown.template = template; dropdown.itemText = itemText; template.gameObject.SetActive(false); dropdown.options.Add(new Dropdown.OptionData("Destination")); return dropdown;
        }

        private static RectTransform CreateRect(string name, Transform parent) { var go = new GameObject(name, typeof(RectTransform)); go.transform.SetParent(parent, false); return go.GetComponent<RectTransform>(); }
        private static Button CreateButton(string label, Transform parent, Vector2 position, Vector2 size) { var go = new GameObject(label + "Button", typeof(RectTransform), typeof(Image), typeof(Button)); go.transform.SetParent(parent, false); go.GetComponent<Image>().color = new Color(0.12f, 0.18f, 0.23f, 0.96f); var rect = go.GetComponent<RectTransform>(); rect.anchorMin = new Vector2(0, 0.38f); rect.anchorMax = new Vector2(0, 1); rect.pivot = new Vector2(0, 0.5f); rect.anchoredPosition = position; rect.sizeDelta = new Vector2(size.x, 0); var text = CreateText("Label", go.transform, Vector2.zero, Vector2.zero); text.alignment = TextAnchor.MiddleCenter; text.text = label; text.fontSize = 16; SetAnchors(text.rectTransform, Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero); return go.GetComponent<Button>(); }
        private static InputField CreateInputField(string name, Transform parent, Vector2 position, Vector2 size) { var go = new GameObject(name, typeof(RectTransform), typeof(Image), typeof(InputField)); go.transform.SetParent(parent, false); go.GetComponent<Image>().color = new Color(0.12f, 0.18f, 0.23f, 0.96f); var rect = go.GetComponent<RectTransform>(); rect.anchorMin = new Vector2(0, 0.38f); rect.anchorMax = new Vector2(0, 1); rect.pivot = new Vector2(0, 0.5f); rect.anchoredPosition = position; rect.sizeDelta = new Vector2(size.x, 0); var text = CreateText("Text", go.transform, Vector2.zero, Vector2.zero); text.text = "Room name"; text.fontSize = 14; SetAnchors(text.rectTransform, Vector2.zero, Vector2.one, new Vector2(6, 0), new Vector2(-6, 0)); go.GetComponent<InputField>().textComponent = text; return go.GetComponent<InputField>(); }
        private static Text CreateText(string name, Transform parent, Vector2 position, Vector2 size) { var go = new GameObject(name, typeof(RectTransform), typeof(Text)); go.transform.SetParent(parent, false); var text = go.GetComponent<Text>(); text.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf"); text.fontSize = 20; text.color = Color.white; var rect = text.rectTransform; rect.anchorMin = new Vector2(0, 0); rect.anchorMax = new Vector2(0, 1); rect.pivot = new Vector2(0, 0.5f); rect.anchoredPosition = position; rect.sizeDelta = new Vector2(size.x == 0 ? 900 : size.x, 0); return text; }
        private static void SetAnchors(RectTransform rect, Vector2 min, Vector2 max, Vector2 offsetMin, Vector2 offsetMax) { rect.anchorMin = min; rect.anchorMax = max; rect.offsetMin = offsetMin; rect.offsetMax = offsetMax; }
        private static void CompactTopBarControls(Component[] controls, float factor)
        {
            var x = 0f;
            foreach (var control in controls)
            {
                if (control == null) continue;
                var rect = control.GetComponent<RectTransform>();
                if (rect == null) continue;
                var width = rect.sizeDelta.x > 0f ? rect.sizeDelta.x : rect.rect.width;
                rect.anchoredPosition = new Vector2(x, rect.anchoredPosition.y);
                rect.sizeDelta = new Vector2(width * factor, rect.sizeDelta.y);
                x += width * factor + 3f;
            }
        }
        private static void SetSerialized(Object target, string property, Object value) { var serialized = new SerializedObject(target); serialized.FindProperty(property).objectReferenceValue = value; serialized.ApplyModifiedPropertiesWithoutUndo(); }
        private static void EnsureDirectory(string path) { if (!System.IO.Directory.Exists(path)) System.IO.Directory.CreateDirectory(path); }
    }
